# POST /api/sheets/{sheetId}/claims/{claimId}/comments — comment a claim: the comment is kept with who wrote it and the
# sheet's today, and COMMENT_ADDED is audited. A blank comment is a 400 and a claim not on the sheet a 404, neither
# writing anything (a viewer, an archived sheet and the as-of view are refused before, see ViewerGuard). Responds with
# the claim as stored.
validate:
  class: net.officefloor.hq.app.claim.ValidateComment
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveComment
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordCommentAdded
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
-- Every comment written on a claim: who wrote it, the sheet's today when it was written and its text (trimmed, not
-- blank), kept in the order written.
CREATE TABLE claim_comment (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200)  NOT NULL,
    claim_id   BIGINT        NOT NULL REFERENCES claim (id),
    written_by VARCHAR(200)  NOT NULL,
    written_on DATE          NOT NULL,
    text       VARCHAR(2000) NOT NULL
);
CREATE INDEX claim_comment_claim ON claim_comment (sheet_id, claim_id, id);
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Stores the comment on the claim, dated the sheet's today. */
public class SaveComment {
    public void save(@Val Claim claim, @Val ClaimComment comment, ClaimRepository claims, SheetRepository sheets) {
        claims.comment(claim, new ClaimComment(comment.by(), sheets.today(claim.sheetId()), comment.text()));
    }
}
package net.officefloor.hq.app.claim;

/** Body of commenting a claim: the comment's text and who writes it. */
public record CommentRequest(String text, String by) {
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;

/** A comment on a claim: who wrote it, the sheet's today when it was written (null until stored) and its text. */
public record ClaimComment(String by, LocalDate date, String text) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the comment's text (trimmed; a blank one is refused) and who writes it (a blank name is refused). */
public class ValidateComment {
    public void validate(@RequestBody CommentRequest request, Out<ClaimComment> comment) throws InvalidClaimException {
        String by = request == null || request.by() == null ? "" : request.by().trim();
        String text = request == null || request.text() == null ? "" : request.text().trim();
        if (by.isEmpty()) {
            throw new InvalidClaimException("Who comments the claim is required");
        }
        if (text.isEmpty()) {
            throw new InvalidClaimException("A comment cannot be empty");
        }
        comment.set(new ClaimComment(by, null, text));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;

/** Writes COMMENT_ADDED to the audit file once the comment is stored, naming the claim (number=<number> when it has
 *  one) and ending with its text. */
public class RecordCommentAdded {
    public void record(@Val Claim claim, @Val ClaimComment comment, PersonRepository people, Audit audit) {
        Person person = people.find(claim.sheetId(), claim.personId());
        audit.record("COMMENT_ADDED sheet=" + claim.sheetId() + " by=" + comment.by() + " person="
                + (person == null ? "" : person.name()) + " amount=" + claim.amount().toPlainString()
                + " date=" + claim.date() + (claim.number() == null ? "" : " number=" + claim.number())
                + " text=" + comment.text());
    }
}
